\begin{align}
u &= x - 1  &  f &= u^2 \\
u' &= 1  &  f' &= 2u
\end{align}

Make the replacement $u = x^2$:

\begin{align}
u &= x^2  &  f &= e^u \\
u' &= 2x  &  f' &= e^u
\end{align}

so

\begin{equation}
f'(x) = \dd{}{f}{u} \dd{}{u}{x} = e^{u} \dd{}{u}{x} = e^{x^2} \cdot 2x
\end{equation}

Make the replacement $u = 1+2x$:

\begin{align}
u &= 1 + 2x  & f &= \ln u \\
u' &= 2  &  f' &= \frac{1}{u}
\end{align}

so

\begin{equation}
f'(x) = \dd{}{f}{u} \dd{}{u}{x} = \frac{1}{u} \dd{}{u}{x} = \frac{2}{1 + 2x}
\end{equation}

Make the replacement $u = 1+2x$:

\begin{align}
u &= 1 + 2x  & f &= 2u^{-1} \\
u' &= 2  &  f' &= -2u^{-2}
\end{align}

so

\begin{equation}
f'(x) = \dd{}{f}{u} \dd{}{u}{x} = -2u^{-2} \cdot \dd{}{u}{x} =
  \frac{-4}{(1 + 2x)^2}
\end{equation}

Use the product rule with:

\begin{align}
u &= \sin x & v &= \cos x\\
u' &= \cos x & v' &= -\sin x
\end{align}

so

\begin{align}
f' &= 2[\sin x(-\sin x) + \cos x(\cos x)] \\
&= 2(\cos^2 x-\sin^2 x) \\
&= 2 \cos 2x\\
\end{align}

Use the chain rule with

\begin{align}
u &= 2x & f &= \sin u \\
u' &= 2 & f' = \cos u
\end{align}

so

\begin{equation}
f' = \cos{u} \cdot 2 = 2 \cos 2 x
\end{equation}

Use the chain rule with

\begin{align}
u &= x^2+2x+3 & f = \tan u\\
u' &= 2x+2 & f' = \sec^2 u\\
\end{align}

so

\begin{align}
f' &= \sec^2 u \cdot u'\\
&= (2x+2)\sec^2(x^2+2x+3)\\
\end{align}

Use the chain rule with

\begin{align}
u &= \cos^2 x & f = e^{u}\\
u' &= \dd{}{}{x}(\cos^2 x) & f' = e^{u}
\end{align}

So

\begin{equation}
f' = e^{u} u' = e^{\cos^2 x} \dd{}{}{x}(\cos^2 x)
\end{equation}

Use the chain rule again with

\begin{align}
u &= \cos x & f = u^{2}\\
u' &= -\sin x & f' = 2u\\
\end{align}

So

\begin{align}
f' &= e^{\cos^2 x}(2uu')\\
&= e^{\cos^2 x}(2\cos x \cdot -\sin x)\\
&= -2 \sin x \cos x e^{\cos^2 x}\\
\end{align}
